from lib import *
S = SS('f84')
R = J('f84')
steps = [
    step("表名:类名 UserProfile 自动转成 user_profile,HTTPRequestLog 转成 http_request_log(连续大写按词拆开),写了 __tablename__ = 'my_custom' 就用它。", t=tl(S(1)), done=lidx(S(1), 'user_profile'), kv=KV([['UserProfile', 'user_profile'], ['HTTPRequestLog', 'http_request_log'], ['__tablename__', '覆盖自动命名']], ['__tablename__'])),
    step("没有主键的模型在类定义的那一刻就报错:ArgumentError「Mapper Mapper[NoPk(nopk)] could not assemble any primary key columns for mapped table 'nopk'」——不是等到查询时。", t=tl(S(2)), mark=lidx(S(2), 'ArgumentError'), kv=KV([['没有主键', '定义类时 ArgumentError']], ['没有主键'])),
    step("Column 类型到 PostgreSQL 的 DDL:String(30) 是 VARCHAR(30),Text 是 TEXT,Numeric(8, 2) 是 NUMERIC(8, 2),DateTime 是 TIMESTAMP WITHOUT TIME ZONE,Enum 在 PG 里建了一个独立的 kind 类型(information_schema 里显示 USER-DEFINED);nullable=False 才有 NOT NULL(Column 默认可空),unique=True 变成 UNIQUE (name),CheckConstraint 变成 CHECK,__table_args__ 里的 Index 在 PG 里建出 ix_product_name_active。注意只有 server_default 会出现在 DDL 里(active DEFAULT true、created DEFAULT now()),Python 端的 default 不会。", t=tl(S(3)), done=lidx(S(3), 'CREATE TABLE', 'PG 里实际的列', 'PG 里的索引'), mark=lidx(S(3), 'DEFAULT true', 'DEFAULT now()'), kv=KV([['Column 默认', '可空'], ['default', 'Python 端,不进 DDL'], ['server_default', '进 DDL,数据库端']], ['default'])),
    step("default 与 server_default 的区别:ORM 发出的 INSERT 列出了所有列(name, note, price, active, created, kind, stock),default 的值(price=0、active=true、created=当前时间、stock=0)是 Python 端算好作为参数传进去的;结果行 p1 的 price 是 0.00。绕过 ORM 直接用 SQL 插入的 raw 行,只有 server_default 生效(active=t、created 非空),而 price 是空——Python 端的 default 没有生效。", t=tl(S(4)), done=lidx(S(4), 'ORM 发出的 INSERT', '结果行'), mark=lidx(S(4), '绕过 ORM'), kv=KV([['default', '只经过 ORM 才生效'], ['server_default', '任何写入途径都生效']], ['default'])),
    step("约束在数据库里:stock=-1 违反 CheckConstraint,重名违反 unique,SQLAlchemy 都抛 IntegrityError,底层(e.orig)分别是 psycopg 的 CheckViolation 与 UniqueViolation;抛出后要先 rollback 才能继续用 session。", t=tl(S(5)), mark=lidx(S(5), 'IntegrityError'), kv=KV([['CheckConstraint', 'IntegrityError / CheckViolation'], ['unique', 'IntegrityError / UniqueViolation']], ['unique'])),
    step("SQLAlchemy 2.0 风格的 Mapped[] 注解:Mapped[str] 配 mapped_column(String(30)) 生成 NOT NULL;Mapped[Optional[str]] 生成可空的 VARCHAR;Mapped[int] 配 default=0 生成 INTEGER NOT NULL;注解决定可空性,与旧式 Column 默认可空相反。", t=tl(S(6)), done=lidx(S(6), 'nick', 'name', 'age'), kv=KV([['Mapped[str]', 'NOT NULL'], ['Mapped[Optional[str]]', '可空'], ['旧式 Column', '默认可空']], ['Mapped[str]'])),
    step("模型类上的东西:Product.name 的类型是 InstrumentedAttribute,类上有 __table__(表名 product、列 id, name, note, …),mapper 映射了 9 个属性、主键是 id;实例上没赋值的属性(note、price)是 None——default 要到 INSERT 时才生效。", t=tl(S(7)), done=lidx(S(7), 'Product.name', 'mapper'), mark=lidx(S(7), '实例的'), kv=KV([['Product.name', 'InstrumentedAttribute'], ['实例没赋值的列', 'None,不是 default']], ['实例没赋值的列'])),
    step("映射到已有的表:先在 PostgreSQL 里手工建 legacy 表,db.reflect() 读出它的列(id INTEGER 非空、title TEXT 非空、score INTEGER 可空);reflect 会把库里所有的表都反射进来,包括 product。", t=tl(S(8)), done=lidx(S(8), '反射出的表', 'product'), kv=KV([['db.reflect()', '读出表结构,不用写模型'], ['范围', '库里所有的表']], ['db.reflect()'])),
]
A = mkartf('f84', 84, 'Flask,SQLAlchemy,Model,Table,DDL,真实验证,动画演示',
    '在真实的 PostgreSQL 上实测 Model 与 Table 的映射:类名到表名的转换、没有主键时定义类就报错、各 Column 类型生成的 DDL 与 PG 里实际的列和索引、default 与 server_default 只在 ORM 与绕过 ORM 时的差别、约束违反的异常类型、Mapped[] 注解决定可空、db.reflect() 映射已有的表。',
    '写一个 Model 类,数据库里到底会生成什么?default 与 server_default 有什么不同?没写主键会怎样?已有的表怎么映射?这篇用真实的 PostgreSQL 逐项对照 SQLAlchemy 生成的 DDL 与数据库里实际的结构。',
    [('server_default', '才会进入 DDL;Python 端的 default 绕过 ORM 就不生效'), ('定义类时', '没有主键的模型在类定义那一刻就报 ArgumentError'), ('Mapped[Optional[...]]', '2.0 风格注解下 Optional 才是可空,旧式 Column 默认可空')],
    [('表名怎么来', '<p>上一篇:<a href="flask-request-db-transaction-boundary.html">Flask 请求与数据库事务边界</a>;下一篇:<a href="flask-lazy-eager-loading.html">Lazy Loading 与 Eager Loading</a>。</p>'), ('没有主键', None), ('类型与 DDL', None), ('default 与 server_default', None), ('约束', None), ('Mapped[] 注解', None), ('模型类上的东西', None), ('反射已有的表', None)],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、psycopg 3.3.6、自己起的 PostgreSQL(非默认端口)', '没有验证:SQLite 与 MySQL 上同样模型生成的 DDL、继承映射(单表、联表)、复合主键与复合外键、列的 onupdate、混入类(mixin)与 __abstract__、Flask-SQLAlchemy 的 db.Table 与 BINDS 一起使用'], 'Model 与 Table 映射')
